param([switch]$Apply)
$ErrorActionPreference='Stop'; Add-Type -AssemblyName System.Drawing
$root=$PSScriptRoot; $asset=Join-Path $root 'common\src\main\resources\assets\akaishi'; $out=Join-Path $root 'gui_layouts\remaining_function_items_preview.png'
$names=@('wireless_identity_card','wireless_portable_terminal','sample_collector','wither_charm','gene_book','life_book','life_embryo','blaze_seed','wither_seed','life_ash','wither_condensate','upgrade_template','potion')
$colors=@('#16232d','#355363','#4cae91','#78d6ad','#d8a25c','#db6b79','#845c45','#8776bc','#c0adf0','#ed7950','#19212d','#afc8c7','#532d47')
$sheet=[Drawing.Bitmap]::new(1040,720);$sg=[Drawing.Graphics]::FromImage($sheet);$sg.Clear([Drawing.Color]::FromArgb(22,29,39));$font=[Drawing.Font]::new('Consolas',9)
try{for($i=0;$i -lt $names.Count;$i++){ $b=[Drawing.Bitmap]::new(32,32);$g=[Drawing.Graphics]::FromImage($b);try{$g.Clear([Drawing.Color]::Transparent);$c=[Drawing.ColorTranslator]::FromHtml($colors[$i]);$dark=[Drawing.Color]::FromArgb(255,12,18,24);$g.FillRectangle([Drawing.SolidBrush]::new($dark),4,5,24,22);$g.FillRectangle([Drawing.SolidBrush]::new($c),6,7,20,18);$g.DrawRectangle([Drawing.Pen]::new([Drawing.Color]::White),6,7,19,17);$g.FillRectangle([Drawing.SolidBrush]::new([Drawing.Color]::FromArgb(190,255,255,255)),9,10,(($i%5)+3),2);$g.FillRectangle([Drawing.SolidBrush]::new($c),10,15,12,(($i%4)+2));$g.FillRectangle([Drawing.SolidBrush]::new([Drawing.Color]::FromArgb(220,8,12,18)),12,21,8,2);if($Apply){$b.Save((Join-Path $asset "textures\item\akaishi_$($names[$i]).png"),[Drawing.Imaging.ImageFormat]::Png)}$x=($i%4)*260+70;$y=[int][Math]::Floor($i/4)*220+15;$sg.DrawImage($b,$x,$y,128,128);$sg.DrawString("akaishi_$($names[$i])",$font,[Drawing.Brushes]::White,$x-50,$y+145)}finally{$g.Dispose();$b.Dispose()}}$sheet.Save($out,[Drawing.Imaging.ImageFormat]::Png);"DRAWN=$($names.Count) APPLIED=$Apply PREVIEW=$out"}finally{$sg.Dispose();$sheet.Dispose();$font.Dispose()}